  description="An advanced course in research methodology for the counseling researcher: formulating research questions and hypotheses, quantitative and qualitative design, sampling and measurement, ethics and consent with minors, data collection and basic analysis, and writing a method section.",
  questions=["What makes a question researchable?", "Which design best answers my question, ethically?", "How do I protect young participants while I learn from them?"],
  importance=["Your thesis and future practice depend on sound method", "Method rigor is an ethical obligation to participants", "The field advances one careful study at a time"],
  misconceptions=["that methodology is statistics, when it is the logic of valid inference", "that qualitative is soft, when it is rigorously systematic"],
  figures=["Donald Campbell", "whose work on validity and design remains foundational", "Barbara Tashakkori", "who advanced mixed methods", "Kenneth Kidder", "whose qualitative rigor shaped the field"],
  settings=["thesis and dissertation work","programme evaluation","clinical research literacy","future doctoral study"],
